  let y = i32(gid.y);
  if (!inBounds(x, y)) {
    return;
  }
  let i = idx(x, y);
  let curO = originIn[i];
  let curAlt = altIn[i];
  let curFlags = flagsIn[i];
  let myOx = curO.x;
  let myOy = curO.y;

